class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
class Solution:
    def sortedArrayToBST(self, nums):
        def build(lo,hi):
            if lo > hi: return None
            mid=(lo+hi)//2
            root=TreeNode(nums[mid])
            root.left=build(lo,mid-1); root.right=build(mid+1,hi)
            return root
        return build(0,len(nums)-1)

